1	//! Exposes heap bounds checks functionality for WebAssembly.
2	//! Bounds checks in WebAssembly are critical for safety, so extreme caution is
3	//! recommended when working on this area of Winch.
4	use super::env::HeapData;
5	use crate::{
6	    Result,
7	    abi::vmctx,
8	    codegen::{CodeGenContext, Emission},
9	    isa::reg::{Reg, writable},
10	    masm::{IntCmpKind, IntScratch, MacroAssembler, OperandSize, RegImm, TrapCode},
11	    stack::TypedReg,
12	};
13	
14	/// A newtype to represent an immediate offset argument for a heap access.
15	#[derive(Debug, Copy, Clone)]
16	pub(crate) struct ImmOffset(u32);
17	
18	impl ImmOffset {
19	    /// Construct an [ImmOffset] from a u32.
20	    pub fn from_u32(raw: u32) -> Self {
21	        Self(raw)
22	    }
23	
24	    /// Return the underlying u32 value.
25	    pub fn as_u32(&self) -> u32 {
26	        self.0
27	    }
28	}
29	
30	/// An enum to represent the heap bounds.
31	#[derive(Debug, Copy, Clone)]
32	pub(crate) enum Bounds {
33	    /// Static, known ahead-of-time.
34	    Static(u64),
35	    /// Dynamic. Loaded at runtime.
36	    Dynamic(TypedReg),
37	}
38	
39	impl Bounds {
40	    /// Construct a [Bounds] from a [TypedReg].
41	    pub fn from_typed_reg(tr: TypedReg) -> Self {
42	        Self::Dynamic(tr)
43	    }
44	
45	    /// Construct a [Bounds] from a u64.
46	    pub fn from_u64(raw: u64) -> Self {
47	        Self::Static(raw)
48	    }
49	
50	    /// Return the underlying [TypedReg] value.
51	    pub fn as_typed_reg(&self) -> TypedReg {
52	        match self {
53	            Self::Dynamic(tr) => *tr,
54	            _ => panic!(),
55	        }
56	    }
57	
58	    /// Return the underlying u64 value.
59	    pub fn as_u64(&self) -> u64 {
60	        match self {
61	            Self::Static(v) => *v,
62	            _ => panic!(),
63	        }
64	    }
65	}
66	
67	/// A newtype to represent a heap access index via a [TypedReg].
68	#[derive(Debug, Copy, Clone)]
69	pub(crate) struct Index(TypedReg);
70	
71	impl Index {
72	    /// Construct an [Index] from a [TypedReg].
73	    pub fn from_typed_reg(tr: TypedReg) -> Self {
74	        Self(tr)
75	    }
76	
77	    /// Return the underlying
78	    pub fn as_typed_reg(&self) -> TypedReg {
79	        self.0
80	    }
81	}
