83	/// Loads the bounds of the dynamic heap.
84	pub(crate) fn load_dynamic_heap_bounds<M>(
85	    context: &mut CodeGenContext<Emission>,
86	    masm: &mut M,
87	    heap: &HeapData,
88	    ptr_size: OperandSize,
89	) -> Result<Bounds>
90	where
91	    M: MacroAssembler,
92	{
93	    let dst = context.any_gpr(masm)?;
94	    match heap.memory.static_heap_size() {
95	        // Constant size, no need to perform a load.
96	        Some(size) => masm.mov(writable!(dst), RegImm::i64(size.cast_signed()), ptr_size)?,
97	
98	        None => {
99	            masm.with_scratch::<IntScratch, _>(|masm, scratch| {
100	                let base = if let Some(offset) = heap.import_from {
101	                    let addr = masm.address_at_vmctx(offset)?;
102	                    masm.load_ptr(addr, scratch.writable())?;
103	                    scratch.inner()
104	                } else {
105	                    vmctx!(M)
106	                };
107	                let addr = masm.address_at_reg(base, heap.current_length_offset)?;
108	                masm.load_ptr(addr, writable!(dst))
109	            })?;
110	        }
111	    }
112	
113	    Ok(Bounds::from_typed_reg(TypedReg::new(
114	        heap.index_type(),
115	        dst,
116	    )))
117	}
118	
119	/// This function ensures the following:
120	/// * The immediate offset and memory access size fit in a single u64. Given:
121	///   that the memory access size is a `u8`, we must guarantee that the immediate
122	///   offset will fit in a `u32`, making the result of their addition fit in a u64
123	///   and overflow safe.
124	/// * Adjust the base index to account for the immediate offset via an unsigned
125	///   addition and check for overflow in case the previous condition is not met.
126	#[inline]
127	pub(crate) fn ensure_index_and_offset<M: MacroAssembler>(
128	    masm: &mut M,
129	    index: Index,
130	    offset: u64,
131	    heap_ty_size: OperandSize,
132	) -> Result<ImmOffset> {
133	    match u32::try_from(offset) {
134	        // If the immediate offset fits in a u32, then we simply return.
135	        Ok(offs) => Ok(ImmOffset::from_u32(offs)),
136	        // Else we adjust the index to be index = index + offset, including an
137	        // overflow check, and return 0 as the offset.
138	        Err(_) => {
139	            masm.checked_uadd(
140	                writable!(index.as_typed_reg().into()),
141	                index.as_typed_reg().into(),
142	                RegImm::i64(offset as i64),
143	                heap_ty_size,
144	                TrapCode::HEAP_OUT_OF_BOUNDS,
145	            )?;
146	
147	            Ok(ImmOffset::from_u32(0))
148	        }
149	    }
150	}
151	
152	/// Performs the out-of-bounds check and returns the heap address if the access
153	/// criteria is in bounds.
154	pub(crate) fn load_heap_addr_checked<M, F>(
155	    masm: &mut M,
156	    context: &mut CodeGenContext<Emission>,
157	    ptr_size: OperandSize,
158	    heap: &HeapData,
159	    enable_spectre_mitigation: bool,
160	    bounds: Bounds,
161	    index: Index,
162	    offset: ImmOffset,
163	    mut emit_check_condition: F,
164	) -> Result<Reg>
165	where
166	    M: MacroAssembler,
167	    F: FnMut(&mut M, Bounds, Index) -> Result<IntCmpKind>,
168	{
169	    let cmp_kind = emit_check_condition(masm, bounds, index)?;
170	
171	    masm.trapif(cmp_kind, TrapCode::HEAP_OUT_OF_BOUNDS)?;
172	    let addr = context.any_gpr(masm)?;
173	
174	    load_heap_addr_unchecked(masm, heap, index, offset, addr, ptr_size)?;
175	    if !enable_spectre_mitigation {
176	        Ok(addr)
177	    } else {
178	        // Conditionally assign 0 to the register holding the base address if
179	        // the comparison kind is met.
180	        let tmp = context.any_gpr(masm)?;
181	        masm.mov(writable!(tmp), RegImm::i64(0), ptr_size)?;
182	        let cmp_kind = emit_check_condition(masm, bounds, index)?;
183	        masm.cmov(writable!(addr), tmp, cmp_kind, ptr_size)?;
184	        context.free_reg(tmp);
185	        Ok(addr)
186	    }
187	}
188	
189	/// Load the requested heap address into the specified destination register.
190	/// This function doesn't perform any bounds checks and assumes the caller
191	/// performed the right checks.
192	pub(crate) fn load_heap_addr_unchecked<M>(
193	    masm: &mut M,
194	    heap: &HeapData,
195	    index: Index,
196	    offset: ImmOffset,
197	    dst: Reg,
198	    ptr_size: OperandSize,
199	) -> Result<()>
200	where
201	    M: MacroAssembler,
202	{
203	    masm.with_scratch::<IntScratch, _>(|masm, scratch| {
204	        let base = if let Some(offset) = heap.import_from {
205	            // If the WebAssembly memory is imported, load the address into
206	            // the scratch register.
207	            masm.load_ptr(masm.address_at_vmctx(offset)?, scratch.writable())?;
208	            scratch.inner()
209	        } else {
210	            // Else if the WebAssembly memory is defined in the current module,
211	            // simply use the `VMContext` as the base for subsequent operations.
212	            vmctx!(M)
213	        };
214	
215	        // Load the base of the memory into the `addr` register.
216	        masm.load_ptr(masm.address_at_reg(base, heap.offset)?, writable!(dst))
217	    })?;
218	
219	    // Start by adding the index to the heap base addr.
220	    let index_reg = index.as_typed_reg().reg;
221	    masm.add(writable!(dst), dst, index_reg.into(), ptr_size)?;
222	
223	    if offset.as_u32() > 0 {
224	        masm.add(
225	            writable!(dst),
226	            dst,
227	            RegImm::i64(offset.as_u32() as i64),
228	            ptr_size,
229	        )?;
230	    }
231	    Ok(())
232	}
