903	    pub fn emit_compute_heap_address_align_checked(
904	        &mut self,
905	        memarg: &MemArg,
906	        access_size: OperandSize,
907	    ) -> Result<Option<Reg>> {
908	        self.emit_check_align(memarg, access_size)?;
909	        self.emit_compute_heap_address(memarg, access_size)
910	    }
