128	    /// # Panics
129	    /// This function panics if self cannot be converted to [`AMode`].
130	    pub fn to_addressing_mode<M: Masm>(
131	        self,
132	        masm: &mut M,
133	        size: OperandSize,
134	        f: impl FnOnce(&mut M, AMode) -> Result<()>,
135	    ) -> Result<()> {
136	        use Address::*;
