139	        match self {
140	            SPIndexedSingle { offset, indexing } => {
141	                let amode = if indexing == Pre {
142	                    AMode::SPPreIndexed { simm9: offset }
143	                } else {
144	                    AMode::SPPostIndexed { simm9: offset }
