200	        OperandSize::S8 => types::I8,
201	        OperandSize::S16 => types::I16,
202	        OperandSize::S32 => types::I32,
203	        OperandSize::S64 => types::I64,
204	        OperandSize::S128 => types::I8X16,
205	    }
